<?php
namespace App\Http\Controllers\Hostel;
use App\Http\Controllers\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;

class HostelController extends Controller
{
 private function sid(): int { return (int)session('school_id',1); }
 private function hostels(){ return DB::table('hostels')->where('school_id',$this->sid()); }
 private function ownedHostel($id){$h=$this->hostels()->where('id',$id)->first();abort_unless($h,404);return $h;}
 private function bedIds(){return DB::table('hostel_beds')->join('hostel_rooms','hostel_rooms.id','=','hostel_beds.hostel_room_id')->whereIn('hostel_rooms.hostel_id',$this->hostels()->pluck('id'))->pluck('hostel_beds.id');}

 public function dashboard(){
  $hs=$this->hostels()->get();$roomIds=DB::table('hostel_rooms')->whereIn('hostel_id',$hs->pluck('id'))->pluck('id');$bedIds=DB::table('hostel_beds')->whereIn('hostel_room_id',$roomIds)->pluck('id');
  return view('hostel.dashboard',['hostels'=>$hs,'hostelCount'=>$hs->count(),'roomCount'=>$roomIds->count(),'bedCount'=>$bedIds->count(),'occupiedBeds'=>DB::table('hostel_allocations')->whereIn('hostel_bed_id',$bedIds)->where('status','active')->distinct('hostel_bed_id')->count('hostel_bed_id'),'visitorCount'=>DB::table('hostel_visitors')->whereIn('hostel_id',$hs->pluck('id'))->whereDate('created_at',today())->count(),'recentVisitors'=>DB::table('hostel_visitors')->whereIn('hostel_id',$hs->pluck('id'))->latest()->limit(8)->get()]);
 }
 public function index(){ $hostels=$this->hostels()->orderBy('name')->paginate(15);return view('hostel.index',compact('hostels')); }
 public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:255','hostel_type'=>'nullable|string|max:30','warden_name'=>'nullable|string|max:255','warden_phone'=>'nullable|string|max:30','address'=>'nullable|string']);$d+=['school_id'=>$this->sid(),'is_active'=>1,'created_at'=>now(),'updated_at'=>now()];DB::table('hostels')->insert($d);return back()->with('success','Hostel created.');}
 public function rooms(){ $hs=$this->hostels()->get();$rooms=DB::table('hostel_rooms')->join('hostels','hostels.id','=','hostel_rooms.hostel_id')->whereIn('hostel_id',$hs->pluck('id'))->select('hostel_rooms.*','hostels.name as hostel_name')->orderBy('hostel_name')->paginate(15);return view('hostel.rooms',compact('rooms','hs')); }
 public function storeRoom(Request $r){$d=$r->validate(['hostel_id'=>'required|integer','room_number'=>'required|string|max:255','capacity'=>'required|integer|min:1|max:100','room_type'=>'nullable|string|max:50','fee_per_term'=>'nullable|numeric|min:0']);$this->ownedHostel($d['hostel_id']);$d+=['status'=>'available','created_at'=>now(),'updated_at'=>now()];DB::table('hostel_rooms')->insert($d);return back()->with('success','Room created.');}
 public function storeBed(Request $r,$room){$r->validate(['bed_number'=>'required|string|max:50']);$rec=DB::table('hostel_rooms')->where('id',$room)->first();abort_unless($rec&&$this->hostels()->where('id',$rec->hostel_id)->exists(),404);DB::table('hostel_beds')->insert(['hostel_room_id'=>$room,'bed_number'=>$r->bed_number,'status'=>'available','created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Bed added.');}
 public function roomTypes(){ $types=DB::table('hostel_room_types')->where('school_id',$this->sid())->paginate(15);return view('hostel.room-types',compact('types')); }
 public function storeRoomType(Request $r){$d=$r->validate(['name'=>'required|string|max:255','description'=>'nullable|string','default_capacity'=>'required|integer|min:1','default_fee_per_term'=>'nullable|numeric|min:0']);$d+=['school_id'=>$this->sid(),'is_active'=>1,'created_at'=>now(),'updated_at'=>now()];DB::table('hostel_room_types')->insert($d);return back()->with('success','Room type created.');}
 public function allocations(){ $bedIds=$this->bedIds();$allocations=DB::table('hostel_allocations')->whereIn('hostel_bed_id',$bedIds)->latest()->paginate(15);$students=DB::table('student_profiles')->limit(500)->get();$beds=DB::table('hostel_beds')->whereIn('id',$bedIds)->where('status','available')->get();$years=DB::table('academic_years')->orderByDesc('id')->get();return view('hostel.allocations',compact('allocations','students','beds','years')); }
 public function storeAllocation(Request $r){$d=$r->validate(['student_id'=>'required|exists:student_profiles,id','hostel_bed_id'=>'required|exists:hostel_beds,id','academic_year_id'=>'required|exists:academic_years,id','start_date'=>'required|date']);$bed=DB::table('hostel_beds')->join('hostel_rooms','hostel_rooms.id','=','hostel_beds.hostel_room_id')->where('hostel_beds.id',$d['hostel_bed_id'])->whereIn('hostel_rooms.hostel_id',$this->hostels()->pluck('id'))->select('hostel_beds.*')->first();abort_unless($bed,404);if(DB::table('hostel_allocations')->where('hostel_bed_id',$bed->id)->where('status','active')->exists())return back()->withErrors(['hostel_bed_id'=>'Bed is already occupied.']);DB::transaction(function()use($d,$bed){DB::table('hostel_allocations')->insert($d+['status'=>'active','created_at'=>now(),'updated_at'=>now()]);DB::table('hostel_beds')->where('id',$bed->id)->update(['status'=>'occupied','updated_at'=>now()]);});return back()->with('success','Student allocated.');}
 public function endAllocation($id){$a=DB::table('hostel_allocations')->where('id',$id)->first();abort_unless($a,404);$bed=DB::table('hostel_beds')->join('hostel_rooms','hostel_rooms.id','=','hostel_beds.hostel_room_id')->where('hostel_beds.id',$a->hostel_bed_id)->select('hostel_beds.*','hostel_rooms.hostel_id')->first();abort_unless($bed&&$this->hostels()->where('id',$bed->hostel_id)->exists(),404);DB::transaction(function()use($a,$bed){DB::table('hostel_allocations')->where('id',$a->id)->update(['status'=>'completed','end_date'=>today(),'updated_at'=>now()]);DB::table('hostel_beds')->where('id',$bed->id)->update(['status'=>'available','updated_at'=>now()]);});return back()->with('success','Allocation closed.');}
 public function wardens(){ $hs=$this->hostels()->get();$wardens=DB::table('hostel_wardens')->whereIn('hostel_id',$hs->pluck('id'))->latest()->paginate(15);$staff=DB::table('staff_profiles')->where('school_id',$this->sid())->where('status','active')->get();return view('hostel.wardens',compact('hs','wardens','staff')); }
 public function storeWarden(Request $r){$d=$r->validate(['hostel_id'=>'required|integer','staff_profile_id'=>'nullable|integer|exists:staff_profiles,id','name'=>'required|string|max:255','phone'=>'nullable|string|max:30','email'=>'nullable|email','shift'=>['required',Rule::in(['general','morning','evening','night'])]]);$this->ownedHostel($d['hostel_id']);$d+=['status'=>'active','created_at'=>now(),'updated_at'=>now()];DB::table('hostel_wardens')->insert($d);return back()->with('success','Warden assigned.');}
 public function visitors(){ $hs=$this->hostels()->get();$visitors=DB::table('hostel_visitors')->whereIn('hostel_id',$hs->pluck('id'))->latest()->paginate(15);$students=DB::table('student_profiles')->limit(500)->get();return view('hostel.visitors',compact('hs','visitors','students')); }
 public function storeVisitor(Request $r){$d=$r->validate(['hostel_id'=>'required|integer','student_id'=>'nullable|integer|exists:student_profiles,id','visitor_name'=>'required|string|max:255','phone'=>'nullable|string|max:30','identity_type'=>'nullable|string|max:40','identity_reference'=>'nullable|string|max:100','relationship_to_student'=>'nullable|string|max:80','purpose'=>'nullable|string|max:255']);$this->ownedHostel($d['hostel_id']);$d+=['status'=>'pending','created_at'=>now(),'updated_at'=>now()];DB::table('hostel_visitors')->insert($d);return back()->with('success','Visitor registered for approval.');}
 public function visitorAction(Request $r,$id){$v=DB::table('hostel_visitors')->where('id',$id)->first();abort_unless($v&&$this->hostels()->where('id',$v->hostel_id)->exists(),404);$action=$r->validate(['action'=>['required',Rule::in(['approve','reject','check_in','check_out'])]])['action'];$d=['updated_at'=>now()];if($action==='approve')$d+=['status'=>'approved','approved_by'=>auth()->id(),'approved_at'=>now()];if($action==='reject')$d['status']='rejected';if($action==='check_in'){abort_unless($v->status==='approved',422);$d+=['status'=>'inside','check_in_at'=>now()];}if($action==='check_out'){abort_unless($v->status==='inside',422);$d+=['status'=>'completed','check_out_at'=>now()];}DB::table('hostel_visitors')->where('id',$id)->update($d);return back()->with('success','Visitor status updated.');}
 public function attendance(){ $ids=$this->bedIds();$students=DB::table('hostel_allocations')->join('hostel_beds','hostel_beds.id','=','hostel_allocations.hostel_bed_id')->join('student_profiles','student_profiles.id','=','hostel_allocations.student_id')->whereIn('hostel_beds.id',$ids)->where('hostel_allocations.status','active')->select('student_profiles.*')->get();$records=DB::table('hostel_attendance')->whereIn('student_id',$students->pluck('id'))->whereDate('attendance_date',request('date',today()))->get();return view('hostel.attendance',compact('students','records')); }
 public function storeAttendance(Request $r){$d=$r->validate(['student_id'=>'required|exists:student_profiles,id','attendance_date'=>'required|date','status'=>['required',Rule::in(['present','absent','leave','outing','medical','late_return'])],'check_in_time'=>'nullable|date_format:H:i','check_out_time'=>'nullable|date_format:H:i']);$valid=DB::table('hostel_allocations')->join('hostel_beds','hostel_beds.id','=','hostel_allocations.hostel_bed_id')->where('hostel_allocations.student_id',$d['student_id'])->where('hostel_allocations.status','active')->whereIn('hostel_beds.id',$this->bedIds())->exists();abort_unless($valid,422);DB::table('hostel_attendance')->updateOrInsert(['student_id'=>$d['student_id'],'attendance_date'=>$d['attendance_date']],$d+['recorded_by'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Attendance saved.');}
 public function fees(){ $ids=$this->bedIds();$allocations=DB::table('hostel_allocations')->whereIn('hostel_bed_id',$ids)->where('status','active')->get();$invoices=DB::table('hostel_fee_invoices')->where('school_id',$this->sid())->latest()->paginate(15);return view('hostel.fees',compact('allocations','invoices')); }
 public function storeInvoice(Request $r){$d=$r->validate(['hostel_allocation_id'=>'required|integer|exists:hostel_allocations,id','fee_head'=>'required|string|max:100','amount'=>'required|numeric|min:.01','issued_on'=>'required|date','due_on'=>'nullable|date']);$a=DB::table('hostel_allocations')->where('id',$d['hostel_allocation_id'])->first();abort_unless($a&&in_array($a->hostel_bed_id,$this->bedIds()->all()),404);$d+=['school_id'=>$this->sid(),'invoice_number'=>'HF-'.now()->format('YmdHis').random_int(100,999),'paid_amount'=>0,'status'=>'unpaid','created_at'=>now(),'updated_at'=>now()];DB::table('hostel_fee_invoices')->insert($d);return back()->with('success','Invoice generated.');}
 public function payInvoice(Request $r,$id){$d=$r->validate(['amount'=>'required|numeric|min:.01','payment_method'=>['required',Rule::in(['cash','upi','card','bank_transfer','cheque'])],'paid_on'=>'required|date','reference_number'=>'nullable|string|max:100']);$i=DB::table('hostel_fee_invoices')->where('id',$id)->where('school_id',$this->sid())->first();abort_unless($i,404);abort_if($i->paid_amount+$d['amount']>$i->amount,422,'Payment exceeds balance.');DB::transaction(function()use($i,$d){DB::table('hostel_fee_payments')->insert($d+['hostel_fee_invoice_id'=>$i->id,'receipt_number'=>'HFR-'.now()->format('YmdHis').random_int(100,999),'received_by'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);$paid=$i->paid_amount+$d['amount'];DB::table('hostel_fee_invoices')->where('id',$i->id)->update(['paid_amount'=>$paid,'status'=>$paid >= $i->amount?'paid':'partial','updated_at'=>now()]);});return back()->with('success','Payment recorded.');}
}
